import{_ as t,a0 as i,w as r,s as d,ao as l,I as n,a1 as p,A as o,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"在软件部署中使用 strace 进行调试 | LCTT x X-CMD","titleTemplate":false,"description":"在软件部署中使用 strace 进行调试 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在软件部署中使用 strace 进行调试 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在软件部署中使用 strace 进行调试 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191114 Debugging Software Deployments with strace","title":"在软件部署中使用 strace 进行调试","tag":"201912","desc":""},"relativePath":"201912/20191114 Debugging Software Deployments with strace.md","filePath":"[post].md"}'),c={name:"201912/20191114 Debugging Software Deployments with strace.md"};function u(f,s,b,g,h,m){const e=i("Link");return r(),d("div",null,[s[62]||(s[62]=l('<h1 id="在软件部署中使用-strace-进行调试" tabindex="-1">在软件部署中使用 strace 进行调试 <a class="header-anchor" href="#在软件部署中使用-strace-进行调试" aria-label="Permalink to “在软件部署中使用 strace 进行调试”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/12/130413poennny2pbrgy9ot.jpg" alt=""></p><p>我的大部分工作都涉及到部署软件系统，这意味着我需要花费很多时间来解决以下问题：</p><ul><li>这个软件可以在原开发者的机器上工作，但是为什么不能在我这里运行？</li><li>这个软件昨天可以在我的机器上工作，但是为什么今天就不行？</li></ul><p>这是一种调试的类型，但是与一般的软件调试有所不同。一般的调试通常只关心代码的逻辑，但是在软件部署中的调试关注的是程序的代码和它所在的运行环境之间的相互影响。即便问题的根源是代码的逻辑错误，但软件显然可以在别的机器上运行的事实意味着这类问题与运行环境密切相关。</p><p>所以，在软件部署过程中，我没有使用传统的调试工具（例如 <code>gdb</code>），而是选择了其它工具进行调试。我最喜欢的用来解决“为什么这个软件无法在这台机器上运行？”这类问题的工具就是 <code>strace</code>。</p><h3 id="什么是-strace" tabindex="-1">什么是 strace？ <a class="header-anchor" href="#什么是-strace" aria-label="Permalink to “什么是 strace？”">​</a></h3>',7)),n("p",null,[p(e,{href:"https://strace.io/"},{default:o(()=>[...s[0]||(s[0]=[a("strace",-1)])]),_:1}),s[3]||(s[3]=a(" 是一个用来“追踪系统调用”的工具。它主要是一个 Linux 工具，但是你也可以在其它系统上使用类似的工具（例如 ",-1)),p(e,{href:"http://dtrace.org/blogs/about/"},{default:o(()=>[...s[1]||(s[1]=[a("DTrace",-1)])]),_:1}),s[4]||(s[4]=a(" 和 ",-1)),p(e,{href:"https://man.openbsd.org/ktrace"},{default:o(()=>[...s[2]||(s[2]=[a("ktrace",-1)])]),_:1}),s[5]||(s[5]=a("）。",-1))]),s[63]||(s[63]=l(`<p>它的基本用法非常简单。只需要在 <code>strace</code> 后面跟上你需要运行的命令，它就会显示出该命令触发的所有系统调用（你可能需要先安装好 <code>strace</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ strace echo Hello</span></span>
<span class="line"><span>...Snip lots of stuff...</span></span>
<span class="line"><span>write(1, &quot;Hello\\n&quot;, 6)                  = 6</span></span>
<span class="line"><span>close(1)                                = 0</span></span>
<span class="line"><span>close(2)                                = 0</span></span>
<span class="line"><span>exit_group(0)                           = ?</span></span>
<span class="line"><span>+++ exited with 0 +++</span></span></code></pre></div><p>这些系统调用都是什么？它们就像是操作系统内核提供的 API。很久以前，软件拥有直接访问硬件的权限。如果软件需要在屏幕上显示一些东西，它将会与视频硬件的端口和内存映射寄存器纠缠不清。当多任务操作系统变得流行以后，这就导致了混乱的局面，因为不同的应用程序将“争夺”硬件，并且一个应用程序的错误可能致使其它应用程序崩溃，甚至导致整个系统崩溃。所以 CPU 开始支持多种不同的特权模式（或者称为“保护环”）。它们让操作系统内核在具有完全硬件访问权限的最高特权模式下运行，于此同时，其它在低特权模式下运行的应用程序必须通过向内核发起系统调用才能够与硬件进行交互。</p><p>在二进制级别上，发起系统调用相比简单的函数调用有一些区别，但是大部分程序都使用标准库提供的封装函数。例如，POSIX C 标准库包含一个 <code>write()</code> 函数，该函数包含用于进行 <code>write</code> 系统调用的所有与硬件体系结构相关的代码。</p><p><img src="https://theartofmachinery.com/images/strace/system_calls.svg" alt=""></p><p>简单来说，一个应用程序与其环境（计算机系统）的交互都是通过系统调用来完成的。所以当软件在一台机器上可以工作但是在另一台机器无法工作的时候，追踪系统调用是一个很好的查错方法。具体地说，你可以通过追踪系统调用分析以下典型操作：</p><ul><li>控制台输入与输出 (IO)</li><li>网络 IO</li><li>文件系统访问以及文件 IO</li><li>进程/线程生命周期管理</li><li>原始内存管理</li><li>访问特定的设备驱动</li></ul><h3 id="什么时候可以使用-strace" tabindex="-1">什么时候可以使用 strace？ <a class="header-anchor" href="#什么时候可以使用-strace" aria-label="Permalink to “什么时候可以使用 strace？”">​</a></h3><p>理论上，<code>strace</code> 适用于任何用户空间程序，因为所有的用户空间程序都需要进行系统调用。<code>strace</code> 对于已编译的低级程序最有效果，但如果你可以避免运行时环境和解释器带来的大量额外输出，则仍然可以与 Python 等高级语言程序一起使用。</p>`,9)),n("p",null,[s[7]||(s[7]=a("当软件在一台机器上正常工作，但在另一台机器上却不能正常工作，同时抛出了有关文件、权限或者不能运行某某命令等模糊的错误信息时，",-1)),s[8]||(s[8]=n("code",null,"strace",-1)),s[9]||(s[9]=a(" 往往能大显身手。不幸的是，它不能诊断高等级的问题，例如数字证书验证错误等。这些问题通常需要组合使用 ",-1)),s[10]||(s[10]=n("code",null,"strace",-1)),s[11]||(s[11]=a("（有时候是 ",-1)),p(e,{href:"https://linux.die.net/man/1/ltrace"},{default:o(()=>[...s[6]||(s[6]=[n("code",null,"ltrace",-1)])]),_:1}),s[12]||(s[12]=a("）和其它高级工具（例如使用 ",-1)),s[13]||(s[13]=n("code",null,"openssl",-1)),s[14]||(s[14]=a(" 命令行工具调试数字证书错误）。",-1))]),s[64]||(s[64]=l(`<p>本文中的示例基于独立的服务器，但是对系统调用的追踪通常也可以在更复杂的部署平台上完成，仅需要找到合适的工具。</p><h3 id="一个简单的例子" tabindex="-1">一个简单的例子 <a class="header-anchor" href="#一个简单的例子" aria-label="Permalink to “一个简单的例子”">​</a></h3><p>假设你正在尝试运行一个叫做 <code>foo</code> 的服务器应用程序，但是发生了以下情况：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ foo</span></span>
<span class="line"><span>Error opening configuration file: No such file or directory</span></span></code></pre></div><p>显然，它没有找到你已经写好的配置文件。之所以会发生这种情况，是因为包管理工具有时候在编译应用程序时指定了自定义的路径，所以你应当遵循特定发行版提供的安装指南。如果错误信息告诉你正确的配置文件应该在什么地方，你就可以在几秒钟内解决这个问题，但如果没有告诉你呢？你该如何找到正确的路径？</p><p>如果你有权访问源代码，则可以通过阅读源代码来解决问题。这是一个好的备用计划，但不是最快的解决方案。你还可以使用类似 <code>gdb</code> 的单步调试器来观察程序的行为，但使用专门用于展示程序与系统环境交互作用的工具 <code>strace</code> 更加有效。</p><p>一开始， <code>strace</code> 产生的大量输出可能会让你不知所措，幸好你可以忽略其中大部分的无用信息。我经常使用 <code>-o</code> 参数把输出的追踪结果保存到单独的文件里：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ strace -o /tmp/trace foo</span></span>
<span class="line"><span>Error opening configuration file: No such file or directory</span></span>
<span class="line"><span>$ cat /tmp/trace</span></span>
<span class="line"><span>execve(&quot;foo&quot;, [&quot;foo&quot;], 0x7ffce98dc010 /* 16 vars */) = 0</span></span>
<span class="line"><span>brk(NULL)                               = 0x56363b3fb000</span></span>
<span class="line"><span>access(&quot;/etc/ld.so.preload&quot;, R_OK)      = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;/etc/ld.so.cache&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>fstat(3, {st_mode=S_IFREG|0644, st_size=25186, ...}) = 0</span></span>
<span class="line"><span>mmap(NULL, 25186, PROT_READ, MAP_PRIVATE, 3, 0) = 0x7f2f12cf1000</span></span>
<span class="line"><span>close(3)                                = 0</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;/lib/x86_64-linux-gnu/libc.so.6&quot;, O_RDONLY|O_CLOEXEC) = 3</span></span>
<span class="line"><span>read(3, &quot;\\177ELF\\2\\1\\1\\3\\0\\0\\0\\0\\0\\0\\0\\0\\3\\0&gt;\\0\\1\\0\\0\\0\\260A\\2\\0\\0\\0\\0\\0&quot;..., 832) = 832</span></span>
<span class="line"><span>fstat(3, {st_mode=S_IFREG|0755, st_size=1824496, ...}) = 0</span></span>
<span class="line"><span>mmap(NULL, 8192, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7f2f12cef000</span></span>
<span class="line"><span>mmap(NULL, 1837056, PROT_READ, MAP_PRIVATE|MAP_DENYWRITE, 3, 0) = 0x7f2f12b2e000</span></span>
<span class="line"><span>mprotect(0x7f2f12b50000, 1658880, PROT_NONE) = 0</span></span>
<span class="line"><span>mmap(0x7f2f12b50000, 1343488, PROT_READ|PROT_EXEC, MAP_PRIVATE|MAP_FIXED|MAP_DENYWRITE, 3, 0x22000) = 0x7f2f12b50000</span></span>
<span class="line"><span>mmap(0x7f2f12c98000, 311296, PROT_READ, MAP_PRIVATE|MAP_FIXED|MAP_DENYWRITE, 3, 0x16a000) = 0x7f2f12c98000</span></span>
<span class="line"><span>mmap(0x7f2f12ce5000, 24576, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_FIXED|MAP_DENYWRITE, 3, 0x1b6000) = 0x7f2f12ce5000</span></span>
<span class="line"><span>mmap(0x7f2f12ceb000, 14336, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_FIXED|MAP_ANONYMOUS, -1, 0) = 0x7f2f12ceb000</span></span>
<span class="line"><span>close(3)                                = 0</span></span>
<span class="line"><span>arch_prctl(ARCH_SET_FS, 0x7f2f12cf0500) = 0</span></span>
<span class="line"><span>mprotect(0x7f2f12ce5000, 16384, PROT_READ) = 0</span></span>
<span class="line"><span>mprotect(0x56363b08b000, 4096, PROT_READ) = 0</span></span>
<span class="line"><span>mprotect(0x7f2f12d1f000, 4096, PROT_READ) = 0</span></span>
<span class="line"><span>munmap(0x7f2f12cf1000, 25186)           = 0</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;/etc/foo/config.json&quot;, O_RDONLY) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>dup(2)                                  = 3</span></span>
<span class="line"><span>fcntl(3, F_GETFL)                       = 0x2 (flags O_RDWR)</span></span>
<span class="line"><span>brk(NULL)                               = 0x56363b3fb000</span></span>
<span class="line"><span>brk(0x56363b41c000)                     = 0x56363b41c000</span></span>
<span class="line"><span>fstat(3, {st_mode=S_IFCHR|0620, st_rdev=makedev(0x88, 0x8), ...}) = 0</span></span>
<span class="line"><span>write(3, &quot;Error opening configuration file&quot;..., 60) = 60</span></span>
<span class="line"><span>close(3)                                = 0</span></span>
<span class="line"><span>exit_group(1)                           = ?</span></span>
<span class="line"><span>+++ exited with 1 +++</span></span></code></pre></div><p><code>strace</code> 输出的第一页通常是低级的进程启动过程。（你可以看到很多 <code>mmap</code>、<code>mprotect</code>、<code>brk</code> 调用，这是用来分配原始内存和映射动态链接库的。）实际上，在查找错误时，最好从下往上阅读 <code>strace</code> 的输出。你可以看到 <code>write</code> 调用在最后返回了错误信息。如果你向上找，你将会看到第一个失败的系统调用是 <code>openat</code>，它在尝试打开 <code>/etc/foo/config.json</code> 时抛出了 <code>ENOENT</code> (“No such file or directory”)的错误。现在我们已经知道了配置文件应该放在哪里。</p><p>这是一个简单的例子，但我敢说在 90% 的情况下，使用 <code>strace</code> 进行调试不需要更多复杂的工作。以下是完整的调试步骤：</p><ol><li>从程序中获得含糊不清的错误信息</li><li>使用 <code>strace</code> 运行程序</li><li>在输出中找到错误信息</li><li>往前追溯并找到第一个失败的系统调用</li></ol><p>第四步中的系统调用很可能向你显示出问题所在。</p><h3 id="小技巧" tabindex="-1">小技巧 <a class="header-anchor" href="#小技巧" aria-label="Permalink to “小技巧”">​</a></h3><p>在开始更加复杂的调试之前，这里有一些有用的调试技巧帮助你高效使用 <code>strace</code>：</p><h4 id="man-是你的朋友" tabindex="-1">man 是你的朋友 <a class="header-anchor" href="#man-是你的朋友" aria-label="Permalink to “man 是你的朋友”">​</a></h4><p>在很多 *nix 操作系统中，你可以通过 <code>man syscalls</code> 查看系统调用的列表。你将会看到类似于 <code>brk(2)</code> 之类的东西，这意味着你可以通过运行 <code>man 2 brk</code> 得到与此相关的更多信息。</p><p>一个小问题：<code>man 2 fork</code> 会显示出在 GNU <code>libc</code> 里封装的 <code>fork()</code> 手册页，而 <code>fork()</code> 现在实际上是由 <code>clone</code> 系统调用实现的。<code>fork</code> 的语义与 <code>clone</code> 相同，但是如果我写了一个含有 <code>fork()</code> 的程序并使用 <code>strace</code> 去调试它，我将找不到任何关于 <code>fork</code> 调用的信息，只能看到 <code>clone</code> 调用。如果将源代码与 <code>strace</code> 的输出进行比较的时候，像这种问题会让人感到困惑。</p><h4 id="使用-o-将输出保存到文件" tabindex="-1">使用 -o 将输出保存到文件 <a class="header-anchor" href="#使用-o-将输出保存到文件" aria-label="Permalink to “使用 -o 将输出保存到文件”">​</a></h4><p><code>strace</code> 可以生成很多输出，所以将输出保存到单独的文件是很有帮助的（就像上面的例子一样）。它还能够在控制台中避免程序自身的输出与 <code>strace</code> 的输出发生混淆。</p><h4 id="使用-s-查看更多的参数" tabindex="-1">使用 -s 查看更多的参数 <a class="header-anchor" href="#使用-s-查看更多的参数" aria-label="Permalink to “使用 -s 查看更多的参数”">​</a></h4><p>你可能已经注意到，错误信息的第二部分没有出现在上面的例子中。这是因为 <code>strace</code> 默认仅显示字符串参数的前 32 个字节。如果你需要捕获更多参数，请向 <code>strace</code> 追加类似于 <code>-s 128</code> 之类的参数。</p><h4 id="y-使得追踪文件或套接字更加容易" tabindex="-1">-y 使得追踪文件或套接字更加容易 <a class="header-anchor" href="#y-使得追踪文件或套接字更加容易" aria-label="Permalink to “-y 使得追踪文件或套接字更加容易”">​</a></h4><p>“一切皆文件”意味着 *nix 系统通过文件描述符进行所有 IO 操作，不管是真实的文件还是通过网络或者进程间管道。这对于编程而言是很方便的，但是在追踪系统调用时，你将很难分辨出 <code>read</code> 和 <code>write</code> 的真实行为。</p><p><code>-y</code> 参数使 <code>strace</code> 在注释中注明每个文件描述符的具体指向。</p><h4 id="使用-p-附加到正在运行的进程中" tabindex="-1">使用 -p 附加到正在运行的进程中 <a class="header-anchor" href="#使用-p-附加到正在运行的进程中" aria-label="Permalink to “使用 -p 附加到正在运行的进程中”">​</a></h4><p>正如我们将在后面的例子中看到的，有时候你想追踪一个正在运行的程序。如果你知道这个程序的进程号为 1337 （可以通过 <code>ps</code> 查询），则可以这样操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ strace -p 1337</span></span>
<span class="line"><span>...system call trace output...</span></span></code></pre></div><p>你可能需要 root 权限才能运行。</p><h4 id="使用-f-追踪子进程" tabindex="-1">使用 -f 追踪子进程 <a class="header-anchor" href="#使用-f-追踪子进程" aria-label="Permalink to “使用 -f 追踪子进程”">​</a></h4><p><code>strace</code> 默认只追踪一个进程。如果这个进程产生了一个子进程，你将会看到创建子进程的系统调用（一般是 <code>clone</code>），但是你看不到子进程内触发的任何调用。</p>`,30)),n("p",null,[s[16]||(s[16]=a("如果你认为在子进程中存在错误，则需要使用 ",-1)),s[17]||(s[17]=n("code",null,"-f",-1)),s[18]||(s[18]=a(" 参数启用子进程追踪功能。这样做的缺点是输出的内容会让人更加困惑。当追踪一个进程时，",-1)),s[19]||(s[19]=n("code",null,"strace",-1)),s[20]||(s[20]=a(" 显示的是单个调用事件流。当追踪多个进程的时候，你将会看到以 ",-1)),s[21]||(s[21]=n("code",null,"<unfinished ...>",-1)),s[22]||(s[22]=a(" 开始的初始调用，接着是一系列针对其它线程的调用，最后才出现以 ",-1)),s[23]||(s[23]=n("code",null,"<... foocall resumed>",-1)),s[24]||(s[24]=a(" 结束的初始调用。此外，你可以使用 ",-1)),s[25]||(s[25]=n("code",null,"-ff",-1)),s[26]||(s[26]=a(" 参数将所有的调用分离到不同的文件中（查看 ",-1)),p(e,{href:"https://linux.die.net/man/1/strace"},{default:o(()=>[...s[15]||(s[15]=[a("strace 手册",-1)])]),_:1}),s[27]||(s[27]=a(" 获取更多信息）。",-1))]),s[65]||(s[65]=n("h4",{id:"使用-e-进行过滤",tabindex:"-1"},[a("使用 -e 进行过滤 "),n("a",{class:"header-anchor",href:"#使用-e-进行过滤","aria-label":"Permalink to “使用 -e 进行过滤”"},"​")],-1)),n("p",null,[s[29]||(s[29]=a("正如你所看到的，默认的追踪输出是所有的系统调用。你可以使用 ",-1)),s[30]||(s[30]=n("code",null,"-e",-1)),s[31]||(s[31]=a(" 参数过滤你需要追踪的调用（查看 ",-1)),p(e,{href:"https://linux.die.net/man/1/strace"},{default:o(()=>[...s[28]||(s[28]=[a("strace 手册",-1)])]),_:1}),s[32]||(s[32]=a("）。这样做的好处是运行过滤后的 ",-1)),s[33]||(s[33]=n("code",null,"strace",-1)),s[34]||(s[34]=a(" 比起使用 ",-1)),s[35]||(s[35]=n("code",null,"grep",-1)),s[36]||(s[36]=a(" 进行二次过滤要更快。老实说，我大部分时间都不会被打扰。",-1))]),s[66]||(s[66]=l(`<h4 id="并非所有的错误都是不好的" tabindex="-1">并非所有的错误都是不好的 <a class="header-anchor" href="#并非所有的错误都是不好的" aria-label="Permalink to “并非所有的错误都是不好的”">​</a></h4><p>一个简单而常用的例子是一个程序在多个位置搜索文件，例如 shell 搜索哪个 <code>bin/</code> 目录包含可执行文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ strace sh -c uname</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>stat(&quot;/home/user/bin/uname&quot;, 0x7ffceb817820) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>stat(&quot;/usr/local/bin/uname&quot;, 0x7ffceb817820) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>stat(&quot;/usr/bin/uname&quot;, {st_mode=S_IFREG|0755, st_size=39584, ...}) = 0</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>“错误信息之前的最后一次失败调用”这种启发式方法非常适合于查找错误。无论如何，自下而上地查找是有道理的。</p><h4 id="c-编程指南非常有助于理解系统调用" tabindex="-1">C 编程指南非常有助于理解系统调用 <a class="header-anchor" href="#c-编程指南非常有助于理解系统调用" aria-label="Permalink to “C 编程指南非常有助于理解系统调用”">​</a></h4>`,5)),n("p",null,[s[38]||(s[38]=a("标准 C 库函数调用不属于系统调用，但它们仅是系统调用之上的唯一一个薄层。所以如果你了解（甚至只是略知一二）如何使用 C 语言，那么阅读系统调用追踪信息就非常容易。例如，如果你在调试网络系统调用，你可以尝试略读 ",-1)),p(e,{href:"https://beej.us/guide/bgnet/html/index.html"},{default:o(()=>[...s[37]||(s[37]=[a("Beej 经典的《网络编程指南》",-1)])]),_:1}),s[39]||(s[39]=a("。",-1))]),s[67]||(s[67]=n("h3",{id:"一个更复杂的调试例子",tabindex:"-1"},[a("一个更复杂的调试例子 "),n("a",{class:"header-anchor",href:"#一个更复杂的调试例子","aria-label":"Permalink to “一个更复杂的调试例子”"},"​")],-1)),s[68]||(s[68]=n("p",null,[a("就像我说的那样，简单的调试例子表现了我在大部分情况下如何使用 "),n("code",null,"strace"),a("。然而，有时候需要一些更加细致的工作，所以这里有一个稍微复杂（且真实）的例子。")],-1)),n("p",null,[p(e,{href:"https://untroubled.org/bcron/"},{default:o(()=>[...s[40]||(s[40]=[a("bcron",-1)])]),_:1}),s[41]||(s[41]=a(" 是一个任务调度器，它是经典 *nix ",-1)),s[42]||(s[42]=n("code",null,"cron",-1)),s[43]||(s[43]=a(" 守护程序的另一种实现。它已经被安装到一台服务器上，但是当有人尝试编辑作业时间表时，发生了以下情况：",-1))]),s[69]||(s[69]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e -u logs</span></span>
<span class="line"><span>bcrontab: Fatal: Could not create temporary file</span></span></code></pre></div><p>好的，现在 bcron 尝试写入一些文件，但是它失败了，也没有告诉我们原因。以下是 <code>strace</code> 的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># strace -o /tmp/trace crontab -e -u logs</span></span>
<span class="line"><span>bcrontab: Fatal: Could not create temporary file</span></span>
<span class="line"><span># cat /tmp/trace</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>openat(AT_FDCWD, &quot;bcrontab.14779.1573691864.847933&quot;, O_RDONLY) = 3</span></span>
<span class="line"><span>mmap(NULL, 8192, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7f82049b4000</span></span>
<span class="line"><span>read(3, &quot;#Ansible: logsagg\\n20 14 * * * lo&quot;..., 8192) = 150</span></span>
<span class="line"><span>read(3, &quot;&quot;, 8192)                       = 0</span></span>
<span class="line"><span>munmap(0x7f82049b4000, 8192)            = 0</span></span>
<span class="line"><span>close(3)                                = 0</span></span>
<span class="line"><span>socket(AF_UNIX, SOCK_STREAM, 0)         = 3</span></span>
<span class="line"><span>connect(3, {sa_family=AF_UNIX, sun_path=&quot;/var/run/bcron-spool&quot;}, 110) = 0</span></span>
<span class="line"><span>mmap(NULL, 8192, PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0) = 0x7f82049b4000</span></span>
<span class="line"><span>write(3, &quot;156:Slogs\\0#Ansible: logsagg\\n20 1&quot;..., 161) = 161</span></span>
<span class="line"><span>read(3, &quot;32:ZCould not create temporary f&quot;..., 8192) = 36</span></span>
<span class="line"><span>munmap(0x7f82049b4000, 8192)            = 0</span></span>
<span class="line"><span>close(3)                                = 0</span></span>
<span class="line"><span>write(2, &quot;bcrontab: Fatal: Could not creat&quot;..., 49) = 49</span></span>
<span class="line"><span>unlink(&quot;bcrontab.14779.1573691864.847933&quot;) = 0</span></span>
<span class="line"><span>exit_group(111)                         = ?</span></span>
<span class="line"><span>+++ exited with 111 +++</span></span></code></pre></div><p>在程序结束之前有一个 <code>write</code> 的错误信息，但是这次有些不同。首先，在此之前没有任何相关的失败系统调用。其次，我们看到这个错误信息是由 <code>read</code> 从别的地方读取而来的。这看起来像是真正的错误发生在别的地方，而 <code>bcrontab</code> 只是在转播这些信息。</p><p>如果你查阅了 <code>man 2 read</code>，你将会看到 <code>read</code> 的第一个参数 (<code>3</code>) 是一个文件描述符，这是 *nix 操作系统用于所有 IO 操作的句柄。你该如何知道文件描述符 3 代表什么？在这种情况下，你可以使用 <code>-y</code> 参数运行 <code>strace</code>（如上文所述），它将会在注释里告诉你文件描述符的具体指向，但是了解如何从上面这种输出中分析追踪结果是很有用的。</p><p>一个文件描述符可以来自于许多系统调用之一（这取决于它是用于控制台、网络套接字还是真实文件等的描述符），但不论如何，我们都可以搜索返回值为 <code>3</code> 的系统调用（例如，在 <code>strace</code> 的输出中查找 <code>=3</code>）。在这次 <code>strace</code> 中可以看到有两个这样的调用：最上面的 <code>openat</code> 以及中间的 <code>socket</code>。<code>openat</code> 打开一个文件，但是紧接着的 <code>close(3)</code> 表明其已经被关闭。（注意：文件描述符可以在打开并关闭后重复使用。）所以 <code>socket</code> 调用才是与此相关的（它是在 <code>read</code> 之前的最后一个），这告诉我们 <code>brcontab</code> 正在与一个网络套接字通信。在下一行，<code>connect</code> 表明文件描述符 3 是一个连接到 <code>/var/run/bcron-spool</code> 的 Unix 域套接字。</p><p>因此，我们需要弄清楚 Unix 套接字的另一侧是哪个进程在监听。有两个巧妙的技巧适用于在服务器部署中调试。一个是使用 <code>netstat</code> 或者较新的 <code>ss</code>。这两个命令都描述了当前系统中活跃的网络套接字，使用 <code>-l</code> 参数可以显示出处于监听状态的套接字，而使用 <code>-p</code> 参数可以得到正在使用该套接字的程序信息。（它们还有更多有用的选项，但是这两个已经足够完成工作了。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ss -pl | grep /var/run/bcron-spool</span></span>
<span class="line"><span>u_str LISTEN 0   128   /var/run/bcron-spool 1466637   * 0   users:((&quot;unixserver&quot;,pid=20629,fd=3))</span></span></code></pre></div><p>这告诉我们 <code>/var/run/bcron-spool</code> 套接字的监听程序是 <code>unixserver</code> 这个命令，它的进程 ID 为 20629。（巧合的是，这个程序也使用文件描述符 <code>3</code> 去连接这个套接字。）</p><p>第二个常用的工具就是使用 <code>lsof</code> 查找相同的信息。它可以列出当前系统中打开的所有文件（或文件描述符）。或者，我们可以得到一个具体文件的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsof /var/run/bcron-spool</span></span>
<span class="line"><span>COMMAND   PID   USER  FD  TYPE  DEVICE              SIZE/OFF  NODE    NAME</span></span>
<span class="line"><span>unixserve 20629 cron  3u  unix  0x000000005ac4bd83  0t0       1466637 /var/run/bcron-spool type=STREAM</span></span></code></pre></div><p>进程 20629 是一个常驻进程，所以我们可以使用 <code>strace -o /tmp/trace -p 20629</code> 去查看该进程的系统调用。如果我们在另一个终端尝试编辑 cron 的计划任务表，就可以在错误发生时捕获到以下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>accept(3, NULL, NULL)                   = 4</span></span>
<span class="line"><span>clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7faa47c44810) = 21181</span></span>
<span class="line"><span>close(4)                                = 0</span></span>
<span class="line"><span>accept(3, NULL, NULL)                   = ? ERESTARTSYS (To be restarted if SA_RESTART is set)</span></span>
<span class="line"><span>--- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=21181, si_uid=998, si_status=0, si_utime=0, si_stime=0} ---</span></span>
<span class="line"><span>wait4(0, [{WIFEXITED(s) &amp;&amp; WEXITSTATUS(s) == 0}], WNOHANG|WSTOPPED, NULL) = 21181</span></span>
<span class="line"><span>wait4(0, 0x7ffe6bc36764, WNOHANG|WSTOPPED, NULL) = -1 ECHILD (No child processes)</span></span>
<span class="line"><span>rt_sigaction(SIGCHLD, {sa_handler=0x55d244bdb690, sa_mask=[CHLD], sa_flags=SA_RESTORER|SA_RESTART, sa_restorer=0x7faa47ab9840}, {sa_handler=0x55d244bdb690, sa_mask=[CHLD], sa_flags=SA_RESTORER|SA_RESTART, sa_restorer=0x7faa47ab9840}, 8) = 0</span></span>
<span class="line"><span>rt_sigreturn({mask=[]})                 = 43</span></span>
<span class="line"><span>accept(3, NULL, NULL)                   = 4</span></span>
<span class="line"><span>clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7faa47c44810) = 21200</span></span>
<span class="line"><span>close(4)                                = 0</span></span>
<span class="line"><span>accept(3, NULL, NULL)                   = ? ERESTARTSYS (To be restarted if SA_RESTART is set)</span></span>
<span class="line"><span>--- SIGCHLD {si_signo=SIGCHLD, si_code=CLD_EXITED, si_pid=21200, si_uid=998, si_status=111, si_utime=0, si_stime=0} ---</span></span>
<span class="line"><span>wait4(0, [{WIFEXITED(s) &amp;&amp; WEXITSTATUS(s) == 111}], WNOHANG|WSTOPPED, NULL) = 21200</span></span>
<span class="line"><span>wait4(0, 0x7ffe6bc36764, WNOHANG|WSTOPPED, NULL) = -1 ECHILD (No child processes)</span></span>
<span class="line"><span>rt_sigaction(SIGCHLD, {sa_handler=0x55d244bdb690, sa_mask=[CHLD], sa_flags=SA_RESTORER|SA_RESTART, sa_restorer=0x7faa47ab9840}, {sa_handler=0x55d244bdb690, sa_mask=[CHLD], sa_flags=SA_RESTORER|SA_RESTART, sa_restorer=0x7faa47ab9840}, 8) = 0</span></span>
<span class="line"><span>rt_sigreturn({mask=[]})                 = 43</span></span>
<span class="line"><span>accept(3, NULL, NULL</span></span></code></pre></div><p>（最后一个 <code>accept</code> 调用没有在追踪期间完成。）不幸的是，这次追踪没有包含我们想要的错误信息。我们没有观察到 <code>bcrontan</code> 往套接字发送或接受的任何信息。然而，我们看到了很多进程管理操作（<code>clone</code>、<code>wait4</code>、<code>SIGCHLD</code>，等等）。这个进程产生了子进程，我们猜测真实的工作是由子进程完成的。如果我们想捕获子进程的追踪信息，就必须往 <code>strace</code> 追加 <code>-f</code> 参数。以下是我们最终使用 <code>strace -f -o /tmp/trace -p 20629</code> 找到的错误信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>21470 openat(AT_FDCWD, &quot;tmp/spool.21470.1573692319.854640&quot;, O_RDWR|O_CREAT|O_EXCL, 0600) = -1 EACCES (Permission denied)</span></span>
<span class="line"><span>21470 write(1, &quot;32:ZCould not create temporary f&quot;..., 36) = 36</span></span>
<span class="line"><span>21470 write(2, &quot;bcron-spool[21470]: Fatal: logs:&quot;..., 84) = 84</span></span>
<span class="line"><span>21470 unlink(&quot;tmp/spool.21470.1573692319.854640&quot;) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>21470 exit_group(111)                   = ?</span></span>
<span class="line"><span>21470 +++ exited with 111 +++</span></span></code></pre></div><p>现在我们知道了进程 ID 21470 在尝试创建文件 <code>tmp/spool.21470.1573692319.854640</code> （相对于当前的工作目录）时得到了一个没有权限的错误。如果我们知道当前的工作目录，就可以得到完整路径并能指出为什么该进程无法在此处创建临时文件。不幸的是，这个进程已经退出了，所以我们不能使用 <code>lsof -p 21470</code> 去找出当前的工作目录，但是我们可以往前追溯，查找进程 ID 21470 使用哪个系统调用改变了它的工作目录。这个系统调用是 <code>chdir</code>（可以在搜索引擎很轻松地找到）。以下是一直往前追溯到服务器进程 ID 20629 的结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>20629 clone(child_stack=NULL, flags=CLONE_CHILD_CLEARTID|CLONE_CHILD_SETTID|SIGCHLD, child_tidptr=0x7faa47c44810) = 21470</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>21470 execve(&quot;/usr/sbin/bcron-spool&quot;, [&quot;bcron-spool&quot;], 0x55d2460807e0 /* 27 vars */) = 0</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>21470 chdir(&quot;/var/spool/cron&quot;)          = 0</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>21470 openat(AT_FDCWD, &quot;tmp/spool.21470.1573692319.854640&quot;, O_RDWR|O_CREAT|O_EXCL, 0600) = -1 EACCES (Permission denied)</span></span>
<span class="line"><span>21470 write(1, &quot;32:ZCould not create temporary f&quot;..., 36) = 36</span></span>
<span class="line"><span>21470 write(2, &quot;bcron-spool[21470]: Fatal: logs:&quot;..., 84) = 84</span></span>
<span class="line"><span>21470 unlink(&quot;tmp/spool.21470.1573692319.854640&quot;) = -1 ENOENT (No such file or directory)</span></span>
<span class="line"><span>21470 exit_group(111)                   = ?</span></span>
<span class="line"><span>21470 +++ exited with 111 +++</span></span></code></pre></div>`,17)),n("p",null,[s[45]||(s[45]=a("（如果你在这里迷糊了，你可能需要阅读 ",-1)),p(e,{href:"https://theartofmachinery.com/2018/11/07/writing_a_nix_shell.html"},{default:o(()=>[...s[44]||(s[44]=[a("我之前有关 *nix 进程管理和 shell 的文章",-1)])]),_:1}),s[46]||(s[46]=a("）",-1))]),s[70]||(s[70]=l(`<p>现在 PID 为 20629 的服务器进程没有权限在 <code>/var/spool/cron/tmp/spool.21470.1573692319.854640</code> 创建文件。最可能的原因就是典型的 *nix 文件系统权限设置。让我们检查一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -ld /var/spool/cron/tmp/</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 Nov  6 05:33 /var/spool/cron/tmp/</span></span>
<span class="line"><span># ps u -p 20629</span></span>
<span class="line"><span>USER       PID %CPU %MEM    VSZ   RSS TTY      STAT START   TIME COMMAND</span></span>
<span class="line"><span>cron     20629  0.0  0.0   2276   752 ?        Ss   Nov14   0:00 unixserver -U /var/run/bcron-spool -- bcron-spool</span></span></code></pre></div><p>这就是问题所在！这个服务进程以 <code>cron</code> 用户运行，但是只有 <code>root</code> 用户才有向 <code>/var/spool/cron/tmp/</code> 目录写入的权限。一个简单 <code>chown cron /var/spool/cron/tmp/</code> 命令就能让 <code>bcron</code> 正常工作。（如果不是这个问题，那么下一个最有可能的怀疑对象是诸如 SELinux 或者 AppArmor 之类的内核安全模块，因此我将会使用 <code>dmesg</code> 检查内核日志。）</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>最初，系统调用追踪可能会让人不知所措，但是我希望我已经证明它们是调试一整套常见部署问题的快速方法。你可以设想一下尝试用单步调试器去调试多进程的 <code>bcron</code> 问题。</p><p>通过一连串的系统调用解决问题是需要练习的，但正如我说的那样，在大多数情况下，我只需要使用 <code>strace</code> 从下往上追踪并查找错误。不管怎样，<code>strace</code> 节省了我很多的调试时间。我希望这也对你有所帮助。</p><hr>`,7)),n("p",null,[s[48]||(s[48]=a("via: ",-1)),p(e,{href:"https://theartofmachinery.com/2019/11/14/deployment_debugging_strace.html"},{default:o(()=>[...s[47]||(s[47]=[a("https://theartofmachinery.com/2019/11/14/deployment_debugging_strace.html",-1)])]),_:1})]),n("p",null,[s[53]||(s[53]=a("作者：",-1)),p(e,{href:"https://theartofmachinery.com"},{default:o(()=>[...s[49]||(s[49]=[a("Simon Arneaud",-1)])]),_:1}),s[54]||(s[54]=a(" 选题：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[50]||(s[50]=[a("lujun9972",-1)])]),_:1}),s[55]||(s[55]=a(" 译者：",-1)),p(e,{href:"https://github.com/hanwckf"},{default:o(()=>[...s[51]||(s[51]=[a("hanwckf",-1)])]),_:1}),s[56]||(s[56]=a(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[52]||(s[52]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[59]||(s[59]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[57]||(s[57]=[a("LCTT",-1)])]),_:1}),s[60]||(s[60]=a(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:o(()=>[...s[58]||(s[58]=[a("Linux中国",-1)])]),_:1}),s[61]||(s[61]=a(" 荣誉推出",-1))])])}const x=t(c,[["render",u]]);export{E as __pageData,x as default};
